//! Inline type / parameter-name annotations for BAML files (inlay hints).
//!
//! Provides `file_annotations(db, file) -> &Vec<InlineAnnotation>` — a Salsa
//! tracked query that walks expression-body functions in a file
//! (top-level functions, class/interface methods, and the synthesized
//! `$init_test` registration functions), recursing into lambda bodies (e.g.
//! the bodies of `test` / `testset` blocks, which lower to lambdas passed to
//! `register_test`). It produces two kinds of hints:
//!
//! ## Type hints on `let` bindings
//!
//! For each `Stmt::Let` **without** a type annotation, we display the inferred
//! type of the binding after the variable name, e.g.:
//!
//! ```baml
//! let x = 42          // → x: int
//! let items = [1, 2]  // → items: int[]
//! ```
//!
//! The hint is positioned at the end of the pattern span (just after the
//! variable name token).
//!
//! ## Parameter-name hints on call expressions
//!
//! For each `Expr::Call { callee, args }` where the callee resolves to a
//! `Ty::Function { params }`, we display the parameter name before each
//! positional argument, e.g.:
//!
//! ```baml
//! foo(42, "hello")  // → foo(x: 42, y: "hello")
//! ```
//!
//! Each hint is positioned at the start of the argument's span.
//!
//! ## Scopes
//!
//! Types are resolved through the source span's ancestor scopes so a
//! binding/expression living in a nested block or lambda resolves without
//! accidentally matching an arena-local id from a different body.
//!
//! ## Suppression
//!
//! We suppress type hints for:
//! - Unknown / error types (noise)
//! - Bindings named `_` (discard patterns)
//!
//! We suppress parameter-name hints when:
//! - The callee type is not `Ty::Function` (no param info)
//! - The param name is `None` (positional-only parameter)
//! - The argument count != param count (variadic / error cases)
//!
//! LLM declarative functions are skipped entirely (and never recursed into), so
//! their synthetic `client` / `function_name` / `args` calls produce no hints.

use baml_base::SourceFile;
use baml_compiler2_ast::{
    Expr, ExprId, Stmt,
    ast::{AstSourceMap, ExprBody, FunctionOrigin},
};
use baml_compiler2_hir::{body::FunctionBody, scope::FileScopeId};
use baml_compiler2_hir_ty::ide::infer_for_scope;
use baml_type::Ty;
use text_size::TextSize;

use crate::render::display_ty_for_file;

type SemanticIndex<'a> = baml_compiler2_hir::semantic_index::FileSemanticIndex<'a>;

// ── Public types ──────────────────────────────────────────────────────────────

/// The semantic kind of an inline annotation, mirroring the LSP `InlayHintKind`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AnnotationKind {
    /// A type hint after a variable name: `x: int`
    Type,
    /// A parameter-name hint before a call argument: `name:`
    Parameter,
}

/// A single inline annotation (inlay hint) to display in the editor.
#[derive(Debug, Clone, PartialEq, Eq, salsa::Update)]
pub struct InlineAnnotation {
    /// Byte offset in the file where the hint is inserted.
    pub offset: TextSize,
    /// The text label to display (e.g. `": int"` or `"name: "`).
    pub label: String,
    /// Semantic kind used by the editor for styling/filtering.
    pub kind: AnnotationKind,
    /// Insert thin space to the left of the hint (between hint and preceding token).
    pub padding_left: bool,
    /// Insert thin space to the right of the hint (between hint and following token).
    pub padding_right: bool,
}

// ── Public entry point ────────────────────────────────────────────────────────

/// Compute inline annotations (inlay hints) for a file.
///
/// Returns annotations sorted in document order (required by the LSP
/// `textDocument/inlayHint` contract).
///
/// Salsa tracked query: walks every function body against type
/// inference (measured 40–150ms on real projects), which is too slow to
/// recompute per request while the file is unchanged. Editors re-request
/// inlay hints on every scroll, so this is the hottest read path.
///
/// Named `file_annotations` (like `file_outline`) because the tracked-query
/// machinery claims the bare name in the type namespace, which would collide
/// with this module.
#[salsa::tracked(returns(ref))]
pub fn file_annotations(
    db: &dyn baml_compiler2_hir::Db,
    file: SourceFile,
) -> Vec<InlineAnnotation> {
    let index = baml_compiler2_hir::file_semantic_index(db, file);

    let mut out: Vec<InlineAnnotation> = Vec::new();

    for &func_loc in baml_compiler2_hir::item_data::file_functions(db, file) {
        let func_data = baml_compiler2_hir::item_data::function_data(db, func_loc);

        // Process user-written functions and methods, plus the compiler's own
        // test-registration functions: `Internal` is the origin the lowering
        // stamps on the synthesized `$init_test*` functions, whose lambda
        // arguments carry the user-authored `test` / `testset` bodies — recurse
        // so those get hints. Synthesized companions and auto-derived methods
        // have no user-authored bodies. Skip LLM declarative functions: we must
        // never surface their synthetic `client` / `function_name` / `args`
        // calls, and since we don't recurse into skipped functions, their
        // internals stay hidden.
        match func_data.metadata.origin {
            FunctionOrigin::UserDefined | FunctionOrigin::Internal => {}
            FunctionOrigin::Companion | FunctionOrigin::AutoDerive => continue,
        }
        if baml_compiler2_hir::item_data::function_llm_meta(db, func_loc).is_some() {
            continue;
        }

        let body = baml_compiler2_hir::body::function_body(db, func_loc);
        let FunctionBody::Expr(expr_body) = body.as_ref() else {
            continue;
        };
        let Some(source_map) = baml_compiler2_hir::body::function_body_source_map(db, func_loc)
        else {
            continue;
        };

        let owner_scope = baml_compiler2_hir::item_data::function_scope(db, func_loc)
            .map(|scope| scope.file_scope_id(db))
            .unwrap_or_else(|| {
                let func_span =
                    baml_compiler2_hir::item_data::function_source_map(db, func_loc).span;
                index.scope_at_offset(func_span.start(), Some(&func_data.name))
            });
        process_body(
            db,
            file,
            index,
            owner_scope,
            expr_body,
            &source_map,
            &mut out,
        );
    }

    // Sort by offset to ensure document order (required by LSP).
    out.sort_by_key(|h| h.offset);
    out
}

/// Emit hints for a single expression body — `let`-binding type hints and call
/// parameter-name hints — then recurse into any lambda bodies it contains
/// (each lambda has its own `ExprBody` arena and source map, e.g. the body of a
/// `test` block lowered to a lambda passed to `register_test`).
fn process_body(
    db: &dyn baml_compiler2_hir::Db,
    file: SourceFile,
    index: &SemanticIndex<'_>,
    owner_scope: FileScopeId,
    body: &ExprBody,
    source_map: &AstSourceMap,
    out: &mut Vec<InlineAnnotation>,
) {
    // ── Type hints for let bindings without annotations ───────────────────────
    for (stmt_id, stmt) in body.stmts.iter() {
        let Stmt::Let { pattern, .. } = stmt else {
            continue;
        };

        // Skip compiler-synthesized bindings — e.g. the accumulator a `${…}`
        // interpolation lowers to (`let " __m3_concat" = ""`). Their spans point
        // inside the backtick template, so a `: T` hint there is noise the user
        // never wrote. Marked at lowering time (see `AstSourceMap::synthetic_stmts`).
        if source_map.is_synthetic_stmt(stmt_id) {
            continue;
        }

        // `let x: T` (Bind with sub-pattern) or a bare type pattern already
        // carries an explicit annotation — skip.
        let pat = &body.patterns[*pattern];
        if matches!(
            pat,
            baml_compiler2_ast::Pattern::Bind {
                subpat: Some(_),
                ..
            } | baml_compiler2_ast::Pattern::Type(_)
        ) {
            continue;
        }

        // Skip `_` / non-simple bindings.
        if pat.binding_name(&body.patterns).is_none() {
            continue;
        }

        let pat_span = source_map.pattern_span(*pattern);
        if pat_span.is_empty() {
            continue;
        }

        // Resolve through the binding's real source scope chain. PatIds are
        // arena-local, so scanning every file scope can hit a foreign body that
        // happens to reuse the same numeric id.
        let mut ty_str: Option<String> = None;
        let use_scope = scope_at_offset_within_body(index, pat_span.start(), owner_scope);
        for file_scope_id in ancestor_scopes_within_body(index, use_scope, owner_scope) {
            let scope_id = index.scope_ids[file_scope_id.index() as usize];
            let Some(inference) = infer_for_scope(db, scope_id) else {
                continue;
            };
            if let Some(ty) = inference.type_of_pat.get(pattern) {
                let ty = ty.clone();
                if !should_suppress_type(&ty) {
                    ty_str = Some(display_ty_for_file(db, file, &ty));
                }
                break;
            }
        }
        let Some(ty_str) = ty_str else {
            continue;
        };

        out.push(InlineAnnotation {
            offset: pat_span.end(),
            label: format!(": {ty_str}"),
            kind: AnnotationKind::Type,
            padding_left: false,
            padding_right: true,
        });
    }

    // ── Parameter-name hints on calls ─────────────────────────────────────────
    // Lambda bodies share this arena, so this one pass covers them too.
    for (expr_id, expr) in body.exprs.iter() {
        if let Expr::Call { callee, args, .. } = expr {
            // Skip synthesized test/testset registration calls — their
            // `name` / `body` / `collector` / `runner` arguments are codegen,
            // not user-facing. We still recurse into their lambda arguments
            // (the actual test bodies), which live in the same arena.
            if is_synthetic_registration(body, *callee) {
                continue;
            }
            // Skip compiler-synthesized wrapping calls — e.g. the
            // `string.from(${expr})` that `${…}` interpolation lowers to.
            // Marked at lowering time (see `AstSourceMap::synthetic_exprs`),
            // so without this every interpolation would get a spurious
            // `value:` parameter hint.
            if source_map.is_synthetic_expr(expr_id) {
                continue;
            }
            let callee_span = source_map.expr_span(*callee);
            if callee_span.is_empty() {
                continue;
            }

            // Find a scope where the callee resolves to a function type.
            // ExprIds are arena-local (per body), so restrict lookup to the
            // callee's source scope chain instead of scanning every scope in
            // the file for the first matching numeric id.
            let use_scope = scope_at_offset_within_body(index, callee_span.start(), owner_scope);
            for file_scope_id in ancestor_scopes_within_body(index, use_scope, owner_scope) {
                let scope_id = index.scope_ids[file_scope_id.index() as usize];
                let Some(inference) = infer_for_scope(db, scope_id) else {
                    continue;
                };
                let Some(callee_ty) = inference.type_of_expr.get(callee).cloned() else {
                    continue;
                };
                let Ty::Function { ref params, .. } = callee_ty else {
                    continue;
                };
                if args.len() != params.len() {
                    continue;
                }
                for (arg, param) in args.iter().zip(params.iter()) {
                    if arg.label.is_some() {
                        continue;
                    }
                    let Some(name) = &param.name else {
                        continue;
                    };
                    let name_str = name.as_str();
                    // `self` is implicit.
                    if name_str == "self" {
                        continue;
                    }
                    let arg_span = source_map.expr_span(arg.expr);
                    if arg_span.is_empty() {
                        continue;
                    }
                    out.push(InlineAnnotation {
                        offset: arg_span.start(),
                        label: format!("{name_str}: "),
                        kind: AnnotationKind::Parameter,
                        padding_left: false,
                        padding_right: false,
                    });
                }
                break;
            }
        }
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Returns `true` for types that would produce noisy or unhelpful hints.
///
/// We suppress:
/// - `Ty::Error` — type-check error, nothing useful to show
/// - `Ty::Unknown` — no useful info
/// - `Ty::Never` — unreachable / error types
fn should_suppress_type(ty: &Ty) -> bool {
    baml_type::contains_error_recovery(ty) || matches!(ty, Ty::Unknown | Ty::Never)
}

/// True if `callee` names a test/testset registration method
/// (`register_test` / `register_test_set`, or the `*_at` forms the
/// synthesized `$init_test` body calls — the same name set the lowering's own
/// `count_register_calls` classifier matches). These calls are emitted by
/// test/testset desugaring; their `name` / `body` / `collector` / `runner`
/// arguments are codegen and shouldn't get parameter-name hints.
///
/// This is a name heuristic: the desugaring allocates these calls without
/// marking them in `AstSourceMap::synthetic_exprs`, so there is no
/// source-map/firewall signal to key on. A user-authored call to a function
/// with one of these names is also suppressed — remove this once the lowering
/// marks registration calls synthetic.
fn is_synthetic_registration(body: &ExprBody, callee: ExprId) -> bool {
    let name = match &body.exprs[callee] {
        Expr::MemberAccess { member, .. } => member.as_str(),
        Expr::Path(segments) => match segments.last() {
            Some(n) => n.as_str(),
            None => return false,
        },
        _ => return false,
    };
    matches!(
        name,
        "register_test" | "register_test_set" | "register_test_at" | "register_test_set_at"
    )
}

fn scope_at_offset_within_body(
    index: &SemanticIndex<'_>,
    offset: TextSize,
    owner_scope: FileScopeId,
) -> FileScopeId {
    let scope_id = index.scope_at_offset(offset, None);
    if scope_is_descendant_or_self(index, scope_id, owner_scope) {
        scope_id
    } else {
        owner_scope
    }
}

fn ancestor_scopes_within_body(
    index: &SemanticIndex<'_>,
    start_scope: FileScopeId,
    owner_scope: FileScopeId,
) -> Vec<FileScopeId> {
    let mut scopes = Vec::new();
    let mut current = Some(start_scope);
    while let Some(scope_id) = current {
        scopes.push(scope_id);
        if scope_id == owner_scope {
            return scopes;
        }
        current = index.scopes[scope_id.index() as usize].parent;
    }
    vec![owner_scope]
}

fn scope_is_descendant_or_self(
    index: &SemanticIndex<'_>,
    scope_id: FileScopeId,
    owner_scope: FileScopeId,
) -> bool {
    scope_id == owner_scope
        || index.scopes[owner_scope.index() as usize]
            .descendants
            .contains(&scope_id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_support::ProjectTest;

    #[test]
    fn lambda_type_hints_use_later_constraints_and_hide_unresolved_types() {
        const SOURCE: &str = r#"
function resolved() -> int {
    let resolved_lambda = (b) -> { 1 }
    let constrained: (int) -> int throws never = resolved_lambda
    constrained(0)
}

function unresolved() -> int {
    let unresolved_lambda = (b) -> { 1 }
    0
}
"#;

        let mut builder = ProjectTest::builder();
        builder.source("main.baml", SOURCE);
        let project = builder.build();
        let hints = file_annotations(&project.db, project.files[0]);

        let binding_offset = |name: &str| {
            let start = SOURCE.find(name).expect("binding should exist");
            TextSize::try_from(start + name.len()).expect("binding offset should fit in TextSize")
        };
        let type_hints_at = |offset| {
            hints
                .iter()
                .filter(|hint| hint.kind == AnnotationKind::Type && hint.offset == offset)
                .map(|hint| hint.label.as_str())
                .collect::<Vec<_>>()
        };

        assert_eq!(
            type_hints_at(binding_offset("resolved_lambda")),
            vec![": (b: int) -> int throws never"]
        );
        assert!(type_hints_at(binding_offset("unresolved_lambda")).is_empty());
        assert!(hints.iter().all(|hint| !hint.label.contains("!error")));
    }

    #[test]
    fn annotations_skip_declarative_llm_synthetic_call_hints() {
        let mut builder = ProjectTest::builder();
        builder.source(
            "main.baml",
            r##"
function summarize(input: string) -> string {
    client: GPT4
    prompt: `summarize ${input}`
}

function echo(x: string) -> string {
    x
}

function use_echo() -> string {
    echo("hi")
}
"##,
        );
        let project = builder.build();

        let hints = file_annotations(&project.db, project.files[0]);
        let labels: Vec<_> = hints.iter().map(|hint| hint.label.as_str()).collect();

        assert!(
            labels.contains(&"x: "),
            "expected regular function call parameter hints to remain, got {labels:?}"
        );
        assert!(
            labels
                .iter()
                .all(|label| !matches!(*label, "client: " | "function_name: " | "args: ")),
            "LLM synthetic call hints should be suppressed, got {labels:?}"
        );
    }

    #[test]
    fn annotations_skip_tagged_template_synthetic_hints() {
        // A custom `//baml:tagged_string` tag used in an expression function
        // desugars to a closure body full of compiler-generated nodes
        // (`__tt_parts`/`__tt_values`/`__tt_cur` accumulators and `.push(...)`
        // calls). None of them should produce inlay hints — only the user's
        // `let q` binding does. Marked synthetic at lowering (see
        // `AstSourceMap::synthetic_stmts`/`synthetic_exprs`), so this holds even
        // if those nodes later gain real spans / lose their type annotations.
        let mut builder = ProjectTest::builder();
        builder.source(
            "main.baml",
            r##"
//baml:tagged_string
function sql(body: (x: int) -> baml.TaggedString) -> string {
    "ok"
}

function demo(items: int[]) -> string {
    let q = sql`SELECT ${1} ${for (let x in items)}c_${x}, ${endfor}done`
    q
}
"##,
        );
        let project = builder.build();
        let hints = file_annotations(&project.db, project.files[0]);

        // The synthesized `.push(...)` calls must not surface `value:`-style hints.
        assert!(
            hints.iter().all(|h| h.kind != AnnotationKind::Parameter),
            "tagged-template desugaring must not emit parameter hints, got {:?}",
            hints.iter().map(|h| h.label.as_str()).collect::<Vec<_>>()
        );
        // The only type hint is the user's `let q: string`; the `__tt_*`
        // accumulators must not contribute their own.
        let type_hints: Vec<_> = hints
            .iter()
            .filter(|h| h.kind == AnnotationKind::Type)
            .map(|h| h.label.as_str())
            .collect();
        assert_eq!(
            type_hints,
            vec![": string"],
            "only the user's `let q` should get a type hint"
        );
    }

    #[test]
    fn annotations_skip_string_interpolation_synthetic_hints() {
        let mut builder = ProjectTest::builder();
        builder.source(
            "main.baml",
            r##"
function greet(name: string, items: int[]) -> string {
    let greeting = `Hi ${name}! you have ${items.length()} items`
    let counted = `count: ${ let n = items.length() }${n} done`
    greeting + counted
}
"##,
        );
        let project = builder.build();

        let hints = file_annotations(&project.db, project.files[0]);
        let labels: Vec<_> = hints.iter().map(|hint| hint.label.as_str()).collect();

        // `${expr}` lowers to `string.from(expr)`; that synthetic wrapper call
        // must not produce a `value:` parameter hint on every interpolation.
        assert!(
            !labels.contains(&"value: "),
            "synthesized string.from() interpolation calls should not get parameter hints, got {labels:?}"
        );
        // The concat-scope accumulator (`let " __m3_concat" = ""`, a
        // compiler-synthesized binding) must not produce a type hint either;
        // real `let` bindings (`greeting`, `counted`) still do, so the
        // suppression is targeted.
        assert!(
            labels.iter().any(|label| label.starts_with(": ")),
            "real let bindings should still get type hints, got {labels:?}"
        );
    }

    #[test]
    fn annotations_inside_test_bodies() {
        let mut builder = ProjectTest::builder();
        builder.source(
            "main.baml",
            r##"
function greet(name: string) -> string {
    name
}

test "greets" {
    let g = greet("x")
    assert.equal(g, "x")
}
"##,
        );
        let project = builder.build();

        let hints = file_annotations(&project.db, project.files[0]);
        let labels: Vec<_> = hints.iter().map(|hint| hint.label.as_str()).collect();

        assert!(
            labels.contains(&"name: "),
            "expected a parameter hint inside the test body, got {labels:?}"
        );
        assert!(
            labels.iter().any(|label| label.starts_with(": ")),
            "expected a let type hint inside the test body, got {labels:?}"
        );
    }

    #[test]
    fn annotations_inside_methods() {
        let mut builder = ProjectTest::builder();
        builder.source(
            "main.baml",
            r##"
function greet(name: string) -> string {
    name
}

class Greeter {
    prefix: string,

    function run(self, name: string) -> string {
        let g = greet(name)
        g
    }
}
"##,
        );
        let project = builder.build();

        let hints = file_annotations(&project.db, project.files[0]);
        let labels: Vec<_> = hints.iter().map(|hint| hint.label.as_str()).collect();

        assert!(
            labels.contains(&"name: "),
            "expected a parameter hint inside the method body, got {labels:?}"
        );
        assert!(
            labels.iter().any(|label| label.starts_with(": ")),
            "expected a let type hint inside the method body, got {labels:?}"
        );
    }

    #[test]
    fn annotations_suppress_test_registration_hints() {
        let mut builder = ProjectTest::builder();
        builder.source(
            "main.baml",
            r##"
testset "math" {
    test "adds" {
        assert.equal(1 + 1, 2)
    }
    test "subtracts" {
        assert.equal(2 - 1, 1)
    }
}
"##,
        );
        let project = builder.build();

        let hints = file_annotations(&project.db, project.files[0]);
        let labels: Vec<_> = hints.iter().map(|hint| hint.label.as_str()).collect();

        assert!(
            labels
                .iter()
                .all(|label| !matches!(*label, "name: " | "body: " | "collector: " | "runner: ")),
            "synthesized test/testset registration hints should be suppressed, got {labels:?}"
        );
    }

    #[test]
    fn call_parameter_hints_use_the_calls_own_scope() {
        let mut builder = ProjectTest::builder();
        let source = r##"
function left(alpha: string) -> string {
    alpha
}

function right(beta: string) -> string {
    beta
}

function earlier() -> string {
    left("x")
}

function later() -> string {
    right("y")
}
"##;
        builder.source("main.baml", source);
        let project = builder.build();

        let hints = file_annotations(&project.db, project.files[0]);
        let y_offset = TextSize::from(
            u32::try_from(source.find("\"y\"").expect("test arg")).expect("offset fits"),
        );
        let labels_at_y: Vec<_> = hints
            .iter()
            .filter(|hint| hint.offset == y_offset)
            .map(|hint| hint.label.as_str())
            .collect();

        assert_eq!(
            labels_at_y,
            vec!["beta: "],
            "expected later's call to use right's parameter, got {labels_at_y:?}"
        );
    }
}

//! Request handlers, in the two shapes the tables in [`super`] expect.

use std::{path::PathBuf, sync::Arc};

use lsp_types::{
    InitializeParams, InitializeResult, SaveOptions, ServerCapabilities, ServerInfo,
    TextDocumentSyncCapability, TextDocumentSyncKind, TextDocumentSyncOptions,
    TextDocumentSyncSaveOptions, WorkspaceFoldersServerCapabilities, WorkspaceServerCapabilities,
};

use crate::{
    error::LspError,
    paths,
    position_codec::{PositionCodec, PositionEncoding},
    snapshot::Snapshot,
    state::{GlobalState, SessionKey, SessionLifecycle},
};

/// What this server can do, for the `initialize` handshake. `encoding` is
/// the session's negotiated position encoding; advertising it is mandatory
/// whenever the client offered `positionEncodings`.
///
/// `open_panel` is whether the host installed
/// [`GlobalState::set_open_panel_handler`]. Code lenses and
/// [`OPEN_PANEL_COMMAND`] are advertised together and only then: a lens is a
/// button for that command, so a host that cannot run it must not show one.
///
/// Diagnostics are push-only (`publishDiagnostics`); the pull provider is
/// deliberately absent so editors never show each diagnostic twice.
/// The BAML-specific protocol versions, published to clients in
/// `capabilities.experimental.baml` so the extension's version-skew check
/// has something to read (it silently skips servers that send nothing).
///
/// The playground numbers mirror the `/api/ws` handshake's `hello` frame
/// (protocol 2, min client 2) — the WS layer is the source of truth for
/// what those versions MEAN; these exist so a client can learn them before
/// opening a socket.
pub(crate) const LSP_PROTOCOL: u32 = 1;
pub(crate) const MIN_SUPPORTED_CLIENT_LSP_PROTOCOL: u32 = 1;
pub(crate) const PLAYGROUND_PROTOCOL: u32 = 2;
pub(crate) const MIN_SUPPORTED_CLIENT_PLAYGROUND_PROTOCOL: u32 = 2;

/// The `BamlServerMetadata` the extension reads from
/// `capabilities.experimental.baml` (camelCase is the wire contract).
fn baml_server_metadata() -> serde_json::Value {
    serde_json::json!({
        "baml": {
            "toolchainVersion": baml_version::CANONICAL_VERSION,
            "lspProtocol": LSP_PROTOCOL,
            "minSupportedClientLspProtocol": MIN_SUPPORTED_CLIENT_LSP_PROTOCOL,
            "playgroundProtocol": PLAYGROUND_PROTOCOL,
            "minSupportedClientPlaygroundProtocol": MIN_SUPPORTED_CLIENT_PLAYGROUND_PROTOCOL,
            "capabilities": ["openPlayground.v1", "listProjects.v1", "playgroundWebSocket.v1"],
        }
    })
}

pub fn server_capabilities(encoding: PositionEncoding, open_panel: bool) -> ServerCapabilities {
    ServerCapabilities {
        position_encoding: Some(encoding.to_lsp_kind()),
        text_document_sync: Some(TextDocumentSyncCapability::Options(
            TextDocumentSyncOptions {
                open_close: Some(true),
                change: Some(TextDocumentSyncKind::INCREMENTAL),
                will_save: Some(false),
                will_save_wait_until: Some(false),
                save: Some(TextDocumentSyncSaveOptions::SaveOptions(SaveOptions {
                    include_text: Some(false),
                })),
            },
        )),
        document_formatting_provider: Some(lsp_types::OneOf::Left(true)),
        hover_provider: Some(lsp_types::HoverProviderCapability::Simple(true)),
        definition_provider: Some(lsp_types::OneOf::Left(true)),
        references_provider: Some(lsp_types::OneOf::Left(true)),
        // `prepare_provider` is what lets the editor grey F2 out on a
        // position this server refuses, instead of failing after the reader
        // has typed a new name.
        rename_provider: Some(lsp_types::OneOf::Right(lsp_types::RenameOptions {
            prepare_provider: Some(true),
            work_done_progress_options: lsp_types::WorkDoneProgressOptions::default(),
        })),
        document_symbol_provider: Some(lsp_types::OneOf::Left(true)),
        workspace_symbol_provider: Some(lsp_types::OneOf::Left(true)),
        semantic_tokens_provider: Some(
            lsp_types::SemanticTokensOptions {
                work_done_progress_options: lsp_types::WorkDoneProgressOptions::default(),
                legend: lsp_types::SemanticTokensLegend {
                    token_types: baml_ide::TOKEN_TYPES
                        .iter()
                        .map(|t| lsp_types::SemanticTokenType::new(t.as_str()))
                        .collect(),
                    token_modifiers: baml_ide::TOKEN_MODIFIERS
                        .iter()
                        .map(|m| lsp_types::SemanticTokenModifier::new(m))
                        .collect(),
                },
                range: Some(true),
                full: Some(lsp_types::SemanticTokensFullOptions::Delta { delta: Some(true) }),
            }
            .into(),
        ),
        inlay_hint_provider: Some(lsp_types::OneOf::Left(true)),
        workspace: Some(WorkspaceServerCapabilities {
            workspace_folders: Some(WorkspaceFoldersServerCapabilities {
                supported: Some(true),
                change_notifications: Some(lsp_types::OneOf::Left(true)),
            }),
            file_operations: None,
        }),
        diagnostic_provider: None,
        // `.` (member/qualifier access) and `@` (attribute names) are the
        // trigger characters: every other position completes from a typed
        // prefix, which the editor already requests on. Items ship fully
        // formed (signature, docs, edit), so there is nothing for a resolve
        // round-trip to add.
        completion_provider: Some(lsp_types::CompletionOptions {
            trigger_characters: Some(vec![".".to_owned(), "@".to_owned()]),
            resolve_provider: Some(false),
            ..lsp_types::CompletionOptions::default()
        }),
        // Lenses ship fully resolved; `codeLens/resolve` is the identity so
        // clients that honour `resolveProvider` get an answer rather than
        // `MethodNotFound`.
        code_lens_provider: open_panel.then_some(lsp_types::CodeLensOptions {
            resolve_provider: Some(true),
        }),
        execute_command_provider: open_panel.then(|| lsp_types::ExecuteCommandOptions {
            commands: vec![OPEN_PANEL_COMMAND.to_owned()],
            work_done_progress_options: lsp_types::WorkDoneProgressOptions::default(),
        }),
        experimental: Some(baml_server_metadata()),

        ..ServerCapabilities::default()
    }
}

pub fn initialize_result(encoding: PositionEncoding, open_panel: bool) -> InitializeResult {
    InitializeResult {
        capabilities: server_capabilities(encoding, open_panel),
        server_info: Some(ServerInfo {
            name: "baml-lsp".to_owned(),
            version: Some(baml_version::CANONICAL_VERSION.to_owned()),
        }),
    }
}

/// The `initializationOptions` this server reads.
#[derive(Debug, Default, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct InitializationOptions {
    #[serde(default)]
    baml_client: BamlClientOptions,
}

#[derive(Debug, Default, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct BamlClientOptions {
    /// A materialized copy of the stdlib stubs; wins over the host's
    /// environment/toolchain default when present.
    #[serde(default)]
    stdlib_dir: Option<PathBuf>,
}

// ── Owner-inline ─────────────────────────────────────────────────────────

pub(super) fn initialize(
    state: &mut GlobalState,
    session: SessionKey,
    params: InitializeParams,
) -> Result<InitializeResult, LspError> {
    let encoding = PositionEncoding::negotiate(
        params
            .capabilities
            .general
            .as_ref()
            .and_then(|general| general.position_encodings.as_deref()),
    );
    let snippet_support = params
        .capabilities
        .text_document
        .as_ref()
        .and_then(|text_document| text_document.completion.as_ref())
        .and_then(|completion| completion.completion_item.as_ref())
        .and_then(|item| item.snippet_support)
        .unwrap_or(false);

    let mut workspace_folders: Vec<PathBuf> = params
        .workspace_folders
        .iter()
        .flatten()
        .filter_map(|folder| paths::canonical_document_path(state.roots(), &folder.uri).ok())
        .collect();
    #[expect(
        deprecated,
        reason = "rootUri is the fallback for clients without workspace folders"
    )]
    if workspace_folders.is_empty()
        && let Some(root_uri) = &params.root_uri
        && let Ok(path) = paths::canonical_document_path(state.roots(), root_uri)
    {
        workspace_folders.push(path);
    }

    if let Some(options) = params.initialization_options {
        match serde_json::from_value::<InitializationOptions>(options) {
            Ok(options) => {
                if let Some(stdlib_dir) = options.baml_client.stdlib_dir {
                    state.set_stdlib_dir(Some(stdlib_dir));
                }
            }
            Err(error) => tracing::warn!(%error, "ignoring malformed initializationOptions"),
        }
    }

    tracing::info!(
        ?workspace_folders,
        ?encoding,
        snippet_support,
        "session initialized"
    );
    let session_state = state.session_mut(session)?;
    session_state.encoding = Some(encoding);
    session_state.snippet_support = snippet_support;
    session_state.workspace_folders = workspace_folders;
    session_state.lifecycle = SessionLifecycle::Initialized;
    Ok(initialize_result(
        encoding,
        state.open_panel_handler().is_some(),
    ))
}

/// The database is kept: a browser reload re-initializes against the same
/// state, and the host tears the process down on `exit`.
pub(super) fn shutdown(
    state: &mut GlobalState,
    session: SessionKey,
    (): (),
) -> Result<(), LspError> {
    state.session_mut(session)?.lifecycle = SessionLifecycle::ShuttingDown;
    Ok(())
}

/// The one command this server implements: focus the BAML playground on a
/// function, a test, or a testset. The id is a contract with the VS Code
/// extension, which registers it client-side and routes it back here as
/// `workspace/executeCommand`.
pub const OPEN_PANEL_COMMAND: &str = "baml.openBamlPanel";

/// The single argument of [`OPEN_PANEL_COMMAND`], and the payload handed to
/// the host. Field names are the wire spelling; every field is optional, so
/// a bare "open the playground" is `{}`.
#[derive(Debug, Clone, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OpenPanelArgs {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub project_path: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub function_name: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub test_name: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub testset_name: Option<String>,
}

/// A resolved open-panel request: what the host is asked to do. `project` is
/// always a real workspace root — resolution happens here, so hosts never
/// re-derive it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OpenPanelRequest {
    pub project: PathBuf,
    pub function_name: Option<String>,
    pub test_name: Option<String>,
    pub testset_name: Option<String>,
}

pub(super) fn execute_command(
    state: &mut GlobalState,
    _session: SessionKey,
    mut params: lsp_types::ExecuteCommandParams,
) -> Result<Option<serde_json::Value>, LspError> {
    if params.command != OPEN_PANEL_COMMAND {
        return Err(LspError::RequestNotSupported(format!(
            "workspace/executeCommand ({})",
            params.command
        )));
    }
    let Some(handler) = state.open_panel_handler().cloned() else {
        return Err(LspError::RequestNotSupported(format!(
            "workspace/executeCommand ({OPEN_PANEL_COMMAND}): this host has no playground"
        )));
    };
    // A missing argument means "just open it"; more than one is a client bug
    // worth reporting rather than guessing at.
    let args: OpenPanelArgs = match params.arguments.len() {
        0 => OpenPanelArgs::default(),
        1 => serde_json::from_value(params.arguments.remove(0)).map_err(|error| {
            LspError::InvalidParams(format!("{OPEN_PANEL_COMMAND} arguments: {error}"))
        })?,
        count => {
            return Err(LspError::InvalidParams(format!(
                "{OPEN_PANEL_COMMAND} takes at most one argument, got {count}"
            )));
        }
    };

    let project = match &args.project_path {
        Some(path) => {
            let path = paths::canonical_physical_path(std::path::Path::new(path));
            state
                .roots()
                .workspace_roots()
                .any(|entry| entry.path == path)
                .then_some(path)
                .ok_or_else(|| {
                    LspError::InvalidParams(format!(
                        "{OPEN_PANEL_COMMAND}: {} is not a workspace root",
                        args.project_path.as_deref().unwrap_or_default()
                    ))
                })?
        }
        // No project named: the sole workspace root is unambiguous, and it is
        // the only shape that exists until the world-viewpoint unit lands.
        None => state
            .roots()
            .workspace_roots()
            .next()
            .map(|entry| entry.path.clone())
            .ok_or_else(|| {
                LspError::RequestFailed(format!("{OPEN_PANEL_COMMAND}: no BAML project is open"))
            })?,
    };

    handler(&OpenPanelRequest {
        project,
        function_name: args.function_name,
        test_name: args.test_name,
        testset_name: args.testset_name,
    });
    Ok(None)
}

/// Code lenses are produced fully resolved.
#[expect(
    clippy::unnecessary_wraps,
    reason = "dispatch-table signature: every handler is fallible"
)]
pub(super) fn code_lens_resolve(
    _state: &mut GlobalState,
    _session: SessionKey,
    lens: lsp_types::CodeLens,
) -> Result<lsp_types::CodeLens, LspError> {
    Ok(lens)
}

// ── Snapshot ─────────────────────────────────────────────────────────────

/// Whole-document formatting. A file that does not parse yields no edits
/// (the diagnostics say why); an unchanged file yields no edits.
#[expect(
    clippy::needless_pass_by_value,
    reason = "dispatch-table signature: handlers own their params"
)]
pub(super) fn formatting(
    snap: &Snapshot,
    params: lsp_types::DocumentFormattingParams,
) -> Result<Option<Vec<lsp_types::TextEdit>>, LspError> {
    let path = paths::canonical_document_path(snap.roots(), &params.text_document.uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    let text = file.text(db);
    let formatted = match baml_fmt::format_salsa(db, file, baml_fmt::FormatOptions::default()) {
        Ok(formatted) => formatted,
        Err(baml_fmt::FormatterError::ParseErrors(_)) => return Ok(None),
        Err(baml_fmt::FormatterError::StrongAstError(error)) => {
            return Err(LspError::RequestFailed(format!(
                "cannot format: {}",
                error.print_with_file_context(&path, text)
            )));
        }
    };
    if formatted == *text {
        return Ok(None);
    }
    // Replace the whole document: [0:0, document end) in the session's
    // encoding, so CRLF and non-ASCII last lines are measured correctly.
    let codec = PositionCodec::new(text, snap.cx().encoding);
    Ok(Some(vec![lsp_types::TextEdit {
        range: lsp_types::Range {
            start: lsp_types::Position::default(),
            end: codec.document_end(),
        },
        new_text: formatted,
    }]))
}

// ── Snapshot lane: position-based features ───────────────────────────────────

/// The (file, byte offset) a position request addresses, in the session's
/// encoding.
fn file_offset(
    snap: &crate::snapshot::Snapshot,
    text_document: &lsp_types::TextDocumentIdentifier,
    position: lsp_types::Position,
) -> Result<(baml_db::SourceFile, text_size::TextSize), LspError> {
    let path = crate::paths::canonical_document_path(snap.roots(), &text_document.uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    let offset = codec.position_to_offset(position)?;
    Ok((file, offset))
}

pub(super) fn completion(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::CompletionParams,
) -> Result<Option<lsp_types::CompletionResponse>, LspError> {
    let position_params = params.text_document_position;
    let (file, offset) = file_offset(
        snap,
        &position_params.text_document,
        position_params.position,
    )?;
    let db = snap.db();
    let items = baml_ide::completions(db, file, offset);
    if items.is_empty() {
        return Ok(None);
    }
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    Ok(Some(lsp_types::CompletionResponse::List(
        lsp_types::CompletionList {
            // Always incomplete, as rust-analyzer's lists are: the set
            // depends on what has been typed, not just on the position. A
            // leading `_` asks for a package's internals, so a client that
            // re-filtered a cached list would answer that question itself —
            // with the one list that deliberately left them out.
            is_incomplete: true,
            items: items
                .iter()
                .enumerate()
                .map(|(rank, item)| {
                    super::proto::completion_item(item, rank, &codec, snap.cx().snippet_support)
                })
                .collect(),
        },
    )))
}

pub(super) fn hover(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::HoverParams,
) -> Result<Option<lsp_types::Hover>, LspError> {
    let position_params = params.text_document_position_params;
    let (file, offset) = file_offset(
        snap,
        &position_params.text_document,
        position_params.position,
    )?;
    let Some(info) = baml_ide::type_at(snap.db(), file, offset) else {
        return Ok(None);
    };
    Ok(Some(lsp_types::Hover {
        contents: lsp_types::HoverContents::Markup(lsp_types::MarkupContent {
            kind: lsp_types::MarkupKind::Markdown,
            value: super::proto::hover_markdown(&info),
        }),
        range: None,
    }))
}

pub(super) fn goto_definition(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::GotoDefinitionParams,
) -> Result<Option<lsp_types::GotoDefinitionResponse>, LspError> {
    let position_params = params.text_document_position_params;
    let (file, offset) = file_offset(
        snap,
        &position_params.text_document,
        position_params.position,
    )?;
    let Some(target) = baml_ide::definition_at(snap.db(), file, offset) else {
        return Ok(None);
    };
    Ok(super::proto::location(snap, target).map(lsp_types::GotoDefinitionResponse::Scalar))
}

pub(super) fn references(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::ReferenceParams,
) -> Result<Option<Vec<lsp_types::Location>>, LspError> {
    let position_params = params.text_document_position;
    let (file, offset) = file_offset(
        snap,
        &position_params.text_document,
        position_params.position,
    )?;
    let db = snap.db();
    let mut targets = baml_ide::usages_at(db, file, offset);
    let include_declaration = params.context.include_declaration;
    if include_declaration
        && let Some(declaration) = baml_ide::definition_at(db, file, offset)
        && !targets.contains(&declaration)
    {
        targets.insert(0, declaration);
    }
    let locations: Vec<lsp_types::Location> = targets
        .into_iter()
        .filter_map(|target| super::proto::location(snap, target))
        .collect();
    Ok((!locations.is_empty()).then_some(locations))
}

/// `textDocument/prepareRename`.
///
/// A refusal is `RequestFailed`, which the client shows to the reader — so [`baml_ide::RenameError`]'s
/// message is the whole explanation they get, and says what is wrong rather
/// than that something is.
pub(super) fn prepare_rename(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::TextDocumentPositionParams,
) -> Result<Option<lsp_types::PrepareRenameResponse>, LspError> {
    let lsp_types::TextDocumentPositionParams {
        text_document,
        position,
    } = params;
    let (file, offset) = file_offset(snap, &text_document, position)?;
    let db = snap.db();
    let target = baml_ide::prepare_rename(db, file, offset)
        .map_err(|error| LspError::RequestFailed(error.to_string()))?;
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    Ok(Some(
        lsp_types::PrepareRenameResponse::RangeWithPlaceholder {
            range: codec.byte_range_to_lsp(target.range),
            placeholder: file.text(db)[target.range].to_string(),
        },
    ))
}

/// `textDocument/rename`.
///
/// The edit is all-or-nothing: `baml_ide::rename` either returns every span
/// or refuses, so a client never applies a rename that covers part of the
/// program. A span whose file has no URI (which no workspace file has) would
/// silently shrink the edit, so that is a refusal too.
pub(super) fn rename(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::RenameParams,
) -> Result<Option<lsp_types::WorkspaceEdit>, LspError> {
    let position = params.text_document_position;
    let (file, offset) = file_offset(snap, &position.text_document, position.position)?;
    let db = snap.db();
    let spans = baml_ide::rename(db, file, offset, &params.new_name)
        .map_err(|error| LspError::RequestFailed(error.to_string()))?;

    let mut changes: std::collections::HashMap<lsp_types::Url, Vec<lsp_types::TextEdit>> =
        std::collections::HashMap::new();
    for span in spans {
        let location = super::proto::location(snap, span).ok_or_else(|| {
            LspError::RequestFailed(format!(
                "`{}` is referenced from a file with no URI; no edit was made",
                params.new_name
            ))
        })?;
        changes
            .entry(location.uri)
            .or_default()
            .push(lsp_types::TextEdit {
                range: location.range,
                new_text: params.new_name.clone(),
            });
    }
    Ok(Some(lsp_types::WorkspaceEdit {
        changes: Some(changes),
        ..lsp_types::WorkspaceEdit::default()
    }))
}

pub(super) fn document_symbol(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::DocumentSymbolParams,
) -> Result<Option<lsp_types::DocumentSymbolResponse>, LspError> {
    let text_document = params.text_document;
    let path = crate::paths::canonical_document_path(snap.roots(), &text_document.uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    let symbols: Vec<lsp_types::DocumentSymbol> = baml_ide::file_outline(db, file)
        .iter()
        .map(|item| super::proto::document_symbol(item, &codec))
        .collect();
    Ok(Some(lsp_types::DocumentSymbolResponse::Nested(symbols)))
}

#[expect(
    clippy::unnecessary_wraps,
    reason = "the dispatch table's snapshot-handler contract is fallible"
)]
pub(super) fn workspace_symbol(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::WorkspaceSymbolParams,
) -> Result<Option<lsp_types::WorkspaceSymbolResponse>, LspError> {
    let query = params.query;
    let db = snap.db();
    // The compiler-visible set: workspace symbols plus the stdlib, so
    // `String` or `deep_copy` are findable — goto-def on the result then
    // rides the stdlib URI mapping.
    let files = baml_db::baml_compiler2_hir::compiler2_all_files(db);
    let symbols = baml_ide::search_symbols(db, &files, &query);
    let infos: Vec<lsp_types::SymbolInformation> = symbols
        .into_iter()
        .filter_map(|symbol| {
            let uri = crate::paths::uri_for_db_path(snap.roots(), &symbol.file.path(db))?;
            let codec = PositionCodec::new(symbol.file.text(db), snap.cx().encoding);
            #[expect(
                deprecated,
                reason = "SymbolInformation::deprecated is an LSP wire field; lsp_types keeps it and struct construction must fill it"
            )]
            Some(lsp_types::SymbolInformation {
                name: symbol.name,
                kind: super::proto::symbol_kind(symbol.kind),
                tags: None,
                deprecated: None,
                location: lsp_types::Location {
                    uri,
                    range: codec.byte_range_to_lsp(symbol.name_span),
                },
                container_name: symbol.container_name,
            })
        })
        .collect();
    Ok(Some(lsp_types::WorkspaceSymbolResponse::Flat(infos)))
}

// ── Snapshot lane: semantic tokens + inlay hints ─────────────────────────────

/// Encode ide-layer tokens with LSP line/character deltas in the session's
/// encoding. Multi-line tokens are split into per-line segments (VS Code has
/// no multiline-token capability); document order in, monotonic deltas out.
fn encode_semantic_tokens(
    tokens: &[baml_ide::SemanticToken],
    codec: &PositionCodec<'_>,
) -> Vec<lsp_types::SemanticToken> {
    let mut out = Vec::with_capacity(tokens.len());
    let (mut prev_line, mut prev_start) = (0u32, 0u32);
    for token in tokens {
        for segment in codec.token_segments(token.range) {
            let delta_line = segment.line - prev_line;
            let delta_start = if delta_line == 0 {
                segment.start_character - prev_start
            } else {
                segment.start_character
            };
            out.push(lsp_types::SemanticToken {
                delta_line,
                delta_start,
                length: segment.length,
                token_type: token.token_type.legend_index(),
                token_modifiers_bitset: token.modifiers.bits(),
            });
            prev_line = segment.line;
            prev_start = segment.start_character;
        }
    }
    out
}

/// The full-tokens response plus the baseline commit for the owner. Shared
/// by the full and (fallback path of the) delta handler.
fn full_tokens_with_commit(
    snap: &crate::snapshot::Snapshot,
    uri: &lsp_types::Url,
) -> Result<(lsp_types::SemanticTokens, crate::state::BaselineCommit), LspError> {
    let path = crate::paths::canonical_document_path(snap.roots(), uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    let encoded = encode_semantic_tokens(baml_ide::semantic_tokens(db, file), &codec);
    let result_id = snap.revision();
    let tokens = Arc::new(encoded);
    Ok((
        lsp_types::SemanticTokens {
            result_id: Some(result_id.0.to_string()),
            data: tokens.as_ref().clone(),
        },
        crate::state::BaselineCommit {
            path,
            baseline: crate::state::TokenBaseline { result_id, tokens },
        },
    ))
}

type CommitOutcome<T> = (Result<T, LspError>, Option<crate::state::BaselineCommit>);

pub(super) fn semantic_tokens_full(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::SemanticTokensParams,
) -> CommitOutcome<Option<lsp_types::SemanticTokensResult>> {
    let text_document = params.text_document;
    match full_tokens_with_commit(snap, &text_document.uri) {
        Ok((tokens, commit)) => (
            Ok(Some(lsp_types::SemanticTokensResult::Tokens(tokens))),
            Some(commit),
        ),
        Err(error) => (Err(error), None),
    }
}

pub(super) fn semantic_tokens_delta(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::SemanticTokensDeltaParams,
) -> CommitOutcome<Option<lsp_types::SemanticTokensFullDeltaResult>> {
    let text_document = params.text_document;
    let previous_result_id = params.previous_result_id;
    let (tokens, commit) = match full_tokens_with_commit(snap, &text_document.uri) {
        Ok(computed) => computed,
        Err(error) => return (Err(error), None),
    };
    // Diff only against the baseline the client says it holds; anything else
    // (evicted on close, another document, a stale id) falls back to full.
    let baseline = snap
        .cx()
        .token_baselines
        .get(&commit.path)
        .filter(|baseline| baseline.result_id.0.to_string() == previous_result_id);
    let Some(baseline) = baseline else {
        return (
            Ok(Some(lsp_types::SemanticTokensFullDeltaResult::Tokens(
                tokens,
            ))),
            Some(commit),
        );
    };

    let previous = baseline.tokens.as_slice();
    let current = commit.baseline.tokens.as_slice();
    let prefix = previous
        .iter()
        .zip(current)
        .take_while(|(a, b)| a == b)
        .count();
    let suffix = previous[prefix..]
        .iter()
        .rev()
        .zip(current[prefix..].iter().rev())
        .take_while(|(a, b)| a == b)
        .count();
    // Edit offsets count *integers*, five per token (LSP flattens the data).
    let edits = if prefix == previous.len() && previous.len() == current.len() {
        Vec::new()
    } else {
        vec![lsp_types::SemanticTokensEdit {
            start: u32::try_from(5 * prefix).unwrap_or(u32::MAX),
            delete_count: u32::try_from(5 * (previous.len() - prefix - suffix)).unwrap_or(u32::MAX),
            data: Some(current[prefix..current.len() - suffix].to_vec()),
        }]
    };
    let delta = lsp_types::SemanticTokensDelta {
        result_id: tokens.result_id,
        edits,
    };
    (
        Ok(Some(lsp_types::SemanticTokensFullDeltaResult::TokensDelta(
            delta,
        ))),
        Some(commit),
    )
}

pub(super) fn semantic_tokens_range(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::SemanticTokensRangeParams,
) -> Result<Option<lsp_types::SemanticTokensRangeResult>, LspError> {
    let (text_document, range) = (params.text_document, params.range);
    let path = crate::paths::canonical_document_path(snap.roots(), &text_document.uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    let start = codec.position_to_offset(range.start)?;
    let end = codec.position_to_offset(range.end)?;
    let tokens = baml_ide::semantic_tokens_in_range(db, file, u32::from(start), u32::from(end));
    Ok(Some(lsp_types::SemanticTokensRangeResult::Tokens(
        lsp_types::SemanticTokens {
            result_id: None,
            data: encode_semantic_tokens(&tokens, &codec),
        },
    )))
}

pub(super) fn inlay_hint(
    snap: &crate::snapshot::Snapshot,
    params: lsp_types::InlayHintParams,
) -> Result<Option<Vec<lsp_types::InlayHint>>, LspError> {
    let (text_document, range) = (params.text_document, params.range);
    let path = crate::paths::canonical_document_path(snap.roots(), &text_document.uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    let start = codec.position_to_offset(range.start)?;
    let end = codec.position_to_offset(range.end)?;
    let hints = baml_ide::file_annotations(db, file)
        .iter()
        .filter(|annotation| start <= annotation.offset && annotation.offset <= end)
        .map(|annotation| lsp_types::InlayHint {
            position: codec.offset_to_position(u32::from(annotation.offset)),
            label: lsp_types::InlayHintLabel::String(annotation.label.clone()),
            kind: Some(match annotation.kind {
                baml_ide::AnnotationKind::Type => lsp_types::InlayHintKind::TYPE,
                baml_ide::AnnotationKind::Parameter => lsp_types::InlayHintKind::PARAMETER,
            }),
            text_edits: None,
            tooltip: None,
            padding_left: Some(annotation.padding_left),
            padding_right: Some(annotation.padding_right),
            data: None,
        })
        .collect::<Vec<_>>();
    Ok(Some(hints))
}

/// One lens per runnable item in the file, each carrying a fully-resolved
/// [`OPEN_PANEL_COMMAND`].
#[expect(
    clippy::needless_pass_by_value,
    reason = "dispatch-table signature: handlers own their params"
)]
pub(super) fn code_lens(
    snap: &Snapshot,
    params: lsp_types::CodeLensParams,
) -> Result<Option<Vec<lsp_types::CodeLens>>, LspError> {
    let path = paths::canonical_document_path(snap.roots(), &params.text_document.uri)?;
    let db = snap.db();
    let Some(file) = db.get_file(&path) else {
        return Err(LspError::FileNotFound(path));
    };
    // Lenses run things, and only a workspace root has a runtime to run them
    // in; stdlib and dependency files are read-only views.
    let Some(project) = snap
        .roots()
        .root_for_path(&path)
        .filter(|entry| entry.kind == baml_db::SourceRootKind::Workspace)
        .map(|entry| entry.path.to_string_lossy().into_owned())
    else {
        return Ok(None);
    };
    let codec = PositionCodec::new(file.text(db), snap.cx().encoding);
    let lenses = baml_ide::file_actions(db, file)
        .into_iter()
        .map(|action| {
            let (title, args) = match action.kind {
                baml_ide::FileActionKind::RunInPlayground => (
                    "▶ Open 🐑 Playground",
                    OpenPanelArgs {
                        project_path: Some(project.clone()),
                        function_name: Some(action.name),
                        ..OpenPanelArgs::default()
                    },
                ),
                baml_ide::FileActionKind::RunTest => (
                    "▶ Run test",
                    OpenPanelArgs {
                        project_path: Some(project.clone()),
                        test_name: Some(action.name),
                        ..OpenPanelArgs::default()
                    },
                ),
                baml_ide::FileActionKind::RunTestSet => (
                    "▶ Run testset",
                    OpenPanelArgs {
                        project_path: Some(project.clone()),
                        testset_name: Some(action.name),
                        ..OpenPanelArgs::default()
                    },
                ),
            };
            lsp_types::CodeLens {
                range: codec.byte_range_to_lsp(action.name_span),
                command: Some(lsp_types::Command {
                    title: title.to_owned(),
                    command: OPEN_PANEL_COMMAND.to_owned(),
                    arguments: Some(vec![serde_json::to_value(&args).unwrap_or_else(|error| {
                        unreachable!("OpenPanelArgs always serializes: {error}")
                    })]),
                }),
                data: None,
            }
        })
        .collect();
    Ok(Some(lenses))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn metadata_is_published_for_the_version_skew_check() {
        // The extension reads `capabilities.experimental.baml` and SILENTLY
        // skips the skew check when it is absent — so an empty `experimental`
        // is not a smaller surface, it is an unchecked deployment.
        let caps = server_capabilities(PositionEncoding::UTF16, false);
        let experimental = caps
            .experimental
            .unwrap_or_else(|| unreachable!("experimental.baml is always published"));
        let baml = &experimental["baml"];
        assert_eq!(baml["lspProtocol"], 1);
        assert_eq!(baml["minSupportedClientLspProtocol"], 1);
        assert_eq!(baml["playgroundProtocol"], 2, "mirrors the WS hello");
        assert_eq!(baml["minSupportedClientPlaygroundProtocol"], 2);
        assert!(baml["toolchainVersion"].is_string());
    }

    #[test]
    fn capabilities_advertise_the_negotiated_encoding() {
        assert_eq!(
            server_capabilities(PositionEncoding::UTF8, false).position_encoding,
            Some(lsp_types::PositionEncodingKind::UTF8)
        );
        assert_eq!(
            server_capabilities(PositionEncoding::UTF16, false).position_encoding,
            Some(lsp_types::PositionEncodingKind::UTF16)
        );
    }

    #[test]
    fn capabilities_are_incremental_sync_push_diagnostics_only() {
        let capabilities = server_capabilities(PositionEncoding::UTF16, false);
        let Some(TextDocumentSyncCapability::Options(sync)) = capabilities.text_document_sync
        else {
            panic!("text sync options expected");
        };
        assert_eq!(sync.change, Some(TextDocumentSyncKind::INCREMENTAL));
        assert_eq!(sync.will_save, Some(false));
        assert!(capabilities.diagnostic_provider.is_none());
    }

    /// Lenses and the command they invoke are advertised together, and only
    /// when the host can actually run it — a lens for a command the server
    /// would reject is a button that does nothing.
    #[test]
    fn code_lens_is_advertised_only_with_a_playground_host() {
        let without = server_capabilities(PositionEncoding::UTF16, false);
        assert!(without.code_lens_provider.is_none());
        assert!(without.execute_command_provider.is_none());

        let with = server_capabilities(PositionEncoding::UTF16, true);
        assert_eq!(
            with.code_lens_provider
                .map(|options| options.resolve_provider),
            Some(Some(true))
        );
        assert_eq!(
            with.execute_command_provider
                .map(|options| options.commands),
            Some(vec![OPEN_PANEL_COMMAND.to_owned()])
        );
    }

    /// The lens payload is the command payload: what a lens serializes must
    /// round-trip through the argument the client sends back.
    #[test]
    fn open_panel_args_round_trip_in_the_wire_spelling() {
        let args = OpenPanelArgs {
            project_path: Some("/ws".to_owned()),
            test_name: Some("adds".to_owned()),
            ..OpenPanelArgs::default()
        };
        let value = serde_json::to_value(&args).unwrap();
        assert_eq!(
            value,
            serde_json::json!({ "projectPath": "/ws", "testName": "adds" }),
            "absent fields are omitted, present ones are camelCase"
        );
        assert_eq!(
            serde_json::from_value::<OpenPanelArgs>(value).unwrap(),
            args
        );
        // A bare open carries no argument at all.
        assert_eq!(
            serde_json::from_value::<OpenPanelArgs>(serde_json::json!({})).unwrap(),
            OpenPanelArgs::default()
        );
    }

    #[test]
    fn initialization_options_are_lenient() {
        let options: InitializationOptions =
            serde_json::from_value(serde_json::json!({ "unrelated": 1 })).unwrap();
        assert!(options.baml_client.stdlib_dir.is_none());
        let options: InitializationOptions = serde_json::from_value(
            serde_json::json!({ "bamlClient": { "stdlibDir": "/toolchain/stdlib" } }),
        )
        .unwrap();
        assert_eq!(
            options.baml_client.stdlib_dir.as_deref(),
            Some(std::path::Path::new("/toolchain/stdlib"))
        );
    }
}

pub(super) enum StdlibSourceRequest {}

#[derive(serde::Serialize, serde::Deserialize)]
