}

#[derive(serde::Serialize, serde::Deserialize)]
pub(super) struct StdlibSourceResult {
    content: String,
}

impl lsp_types::request::Request for StdlibSourceRequest {
    type Params = StdlibSourceParams;
    type Result = StdlibSourceResult;
