#[test]
fn stdlib_source_and_nested_navigation_without_disk_sources() {
    let mut h = Harness::new();
    let session = SessionKey(1);
    h.fs.add_project(&h.ws);
    let text = "function main() -> string { baml.env.get_or_panic(\"KEY\") }";
    h.fs.write(h.ws.join("main.baml"), text);
    h.init_session(session, &[]);
    h.settle();
    let target = h
        .request(
            session,
            "textDocument/definition",
            json!({
                "textDocument": { "uri": h.uri("main.baml") },
                "position": { "line": 0, "character": text.find("get_or_panic").unwrap() + 2 }
            }),
        )
        .unwrap();
    let uri = Url::parse(target["uri"].as_str().unwrap()).unwrap();
    assert_eq!(uri.as_str(), "baml-stdlib:/baml/ns_env/env.baml");
    let response = h
        .request(session, "baml/stdlibSource", json!({ "uri": uri }))
        .unwrap();
    let content = response["content"].as_str().unwrap();
    assert_eq!(
        content,
        include_str!("../../baml_builtins2/baml_std/baml/ns_env/env.baml")
    );
    let offset = content.find("root.sys.panic").unwrap() + "root.sys.".len();
    let codec = baml_lsp::position_codec::PositionCodec::new(
        content,
        baml_lsp::position_codec::PositionEncoding::UTF16,
    );
    let params = json!({ "textDocument": { "uri": uri }, "position": codec.offset_to_position(offset.try_into().unwrap()) });
    let nested = h
        .request(session, "textDocument/definition", params.clone())
        .unwrap();
    assert!(
        nested["uri"]
            .as_str()
            .unwrap()
            .starts_with("baml-stdlib:/baml/ns_sys/")
    );
    assert!(
        !h.request(session, "textDocument/hover", params)
            .unwrap()
            .is_null()
    );
    for method in [
        "textDocument/semanticTokens/full",
        "textDocument/documentSymbol",
    ] {
        assert!(
            !h.request(session, method, json!({ "textDocument": { "uri": uri } }))
                .unwrap()
                .is_null()
        );
    }
    h.open(session, &uri, 1, "invalid replacement");
    h.change(session, &uri, 2, "changed");
    h.settle();
    let path = baml_lsp::paths::canonical_document_path(h.state.roots(), &uri).unwrap();
    assert!(h.state.open_document(&path).is_none());
    assert_eq!(
        h.request(session, "baml/stdlibSource", json!({ "uri": uri }))
            .unwrap(),
        response
    );
    for invalid in [
        "file:///etc/passwd",
        "baml-stdlib:/missing.baml",
        "baml-stdlib://host/baml/ns_env/env.baml",
    ] {
        assert!(
            h.request(session, "baml/stdlibSource", json!({ "uri": invalid }))
                .is_err()
        );
    }
}

#[test]
fn semantic_tokens_delta_edits_only_the_changed_region() {
    let mut harness = feature_harness();
    let funcs = harness.uri("funcs.baml");

    let full = harness
        .request(
            SessionKey(1),
            "textDocument/semanticTokens/full",
            serde_json::json!({ "textDocument": { "uri": funcs } }),
        )
        .expect("full tokens succeed");
    let result_id = full["resultId"].as_str().expect("result id").to_owned();
    let data = full["data"].as_array().expect("token data");
    assert!(!data.is_empty(), "fixture produces tokens");

    // Unchanged document → an empty edit list against the same baseline.
    let delta = harness
        .request(
            SessionKey(1),
            "textDocument/semanticTokens/full/delta",
            serde_json::json!({
                "textDocument": { "uri": funcs },
                "previousResultId": result_id,
            }),
        )
        .expect("delta succeeds");
    assert_eq!(
        delta["edits"].as_array().map(Vec::len),
        Some(0),
        "got: {delta}"
    );

    // Append a declaration; the delta must be an edit, not a full resend.
    let changed =
        format!("{FUNCS_FIXTURE}\nfunction shout(p: Person) -> string {{\n    p.name\n}}\n");
    harness.open(SessionKey(1), &funcs, 1, FUNCS_FIXTURE);
    harness.settle();
    harness.change(SessionKey(1), &funcs, 2, &changed);
    harness.settle();
    let delta = harness
        .request(
            SessionKey(1),
            "textDocument/semanticTokens/full/delta",
            serde_json::json!({
                "textDocument": { "uri": funcs },
                "previousResultId": delta["resultId"].as_str().unwrap_or(&result_id),
            }),
        )
        .expect("delta succeeds");
    let edits = delta["edits"].as_array().expect("edits, not a full resend");
    assert_eq!(edits.len(), 1, "one contiguous edit, got: {delta}");

    // A stale/unknown baseline falls back to full tokens.
    let fallback = harness
        .request(
            SessionKey(1),
            "textDocument/semanticTokens/full/delta",
            serde_json::json!({
                "textDocument": { "uri": funcs },
                "previousResultId": "not-a-result-id",
            }),
        )
        .expect("delta succeeds");
    assert!(
        fallback.get("data").is_some(),
        "full fallback, got: {fallback}"
    );
}

